<?php
declare(strict_types=1);
namespace DigiForge\Portal;
use DigiForge\Research\{CommercialResearchRepository,ResearchExecution,ResearchExecutionJournal};
use DigiForge\AI\MonetaryReservationRepository;
use WP_Error;
/** Normal portal forms over existing action/nonce; no scheduler or provider switch is activated. */
final class ResearchExecutionPanel {
 public function __construct(private ?ResearchExecution $execution=null){$this->execution??=new ResearchExecution();}
 public function render(string $shop):void {
  if(ResearchExecutionJournal::access($shop) instanceof WP_Error){echo '<p>Queued research needs current Shop 2 research and AI authorization. Manual research remains available.</p>';return;}
  echo '<section id="df-queued-research"><h3>Queued source-grounded research</h3><p>Recorded/manual source acquisition → freshness checks → bounded background concepts → human selection and approval. Sources are declarations, not verified demand. No automatic scheduler activation. Network execution is disabled by default and STOP ALL remains effective.</p>';
  $sources=(new CommercialResearchRepository())->recent($shop,50);$jobs=(new ResearchExecutionJournal())->recent();if($sources instanceof WP_Error||$jobs instanceof WP_Error){echo '<p role="alert">Queued research evidence is unavailable. Execution is held.</p></section>';return;}
  $run='research-'.wp_generate_uuid4();$started=gmdate('Y-m-d H:i:s');$this->form('enqueue');echo '<input type="hidden" name="request_key" value="'.esc_attr(wp_generate_uuid4()).'"><input type="hidden" name="run_id" value="'.esc_attr($run).'"><input type="hidden" name="started_at" value="'.esc_attr($started).'"><fieldset><legend>Saved opportunities (choose up to five)</legend>';
  foreach($sources as $s)if($s['stage']==='RESEARCH_READY')echo '<label><input type="checkbox" name="sources[]" value="'.esc_attr($s['hash']).'"> '.esc_html($s['title'].' · '.$s['family']).'</label>';
  echo '</fieldset><label>Maximum opportunities<input name="maximum" type="number" min="1" max="5" value="1" required></label><label>Maximum source age (days)<input name="freshness_days" type="number" min="1" max="90" value="30" required></label><label>Your maximum per-source charge (a budget ceiling, not a provider price)<input name="per_task_ceiling" inputmode="decimal" maxlength="16" required></label><label>Original policy currency<input name="currency" pattern="[A-Z]{3}" maxlength="3" required></label>';$this->confirm('Prepare this immutable research intent only; do not dispatch or approve');echo '<button class="df-button">Queue research intent</button></form>';
  foreach($jobs as $j){echo '<details><summary>'.esc_html($j['state'].' · run '.$j['id'].' · '.count($j['results']).'/'.count($j['identity']['sources']).' completed').'</summary><p role="status">'.esc_html($j['identity']['mode']==='OFFLINE_SIMULATOR'?'SYNTHETIC OFFLINE SIMULATION — no real-provider acceptance':'Governed network mode — disabled unless independently authorized').'</p><p>Acquisition: recorded/manual source evidence. No new observed facts or market volumes are inferred.</p><p>Current event <code>'.esc_html($j['event_sha256']).'</code>. Cancellation stops this local workflow; it does not cancel provider work or infer a refund. Unknown reservations stay held.</p>';
   if(isset($j['failure_class']))echo '<p role="alert">'.esc_html($j['failure_class']).'</p>';
   if($j['usage_id']>0)echo '<p>Reservation/usage '.esc_html((string)$j['usage_id']).' retained. '.($j['identity']['mode']==='OFFLINE_SIMULATOR'?'Simulation is not actual provider usage or a billable charge.':'Actual charges require existing provider statement reconciliation.').'</p>';
   $cost=$this->execution->costEvidence($shop,$j['id']);if($cost instanceof WP_Error)echo '<p role="alert">Cost evidence unavailable; no refund or provider charge is assumed.</p>';else foreach($cost['items']as $item){echo '<p>'.esc_html('Usage '.$item['usage_id'].' · '.$item['provider'].' / '.$item['model'].' · task ceiling '.$item['currency'].' '.$item['operator_task_ceiling'].' · reserved maximum '.$item['reserved_maximum'].' · actual charge '.($item['actual_charge']??'UNKNOWN').' · '.$item['cost_state']).'</p>';if($j['identity']['mode']==='NETWORK'&&$item['observed_provider_usage']!==null){$this->form('reconcile',$j);echo '<input type="hidden" name="usage_id" value="'.esc_attr((string)$item['usage_id']).'"><label>Original provider statement for this exact metered response<input type="file" name="statement_file" accept=".json,application/json" required></label>';$this->confirm('I reviewed this exact original invoice line; this records actual cost, not a refund, successful research or provider execution');echo '<button class="df-button">Review original statement evidence</button></form>';}}

   if($j['state']==='QUEUED'){$this->form('quote',$j);echo '<label>Original reviewed provider quote document<input type="file" name="quote_file" accept=".json,application/json" required></label>';$this->confirm('I reviewed the original inclusive quote for this exact request, model, currency and validity');echo '<button class="df-button">Import quote evidence file</button></form>';}
   if(in_array($j['state'],['QUEUED','WAITING'],true)){$this->form('step',$j);$this->confirm('Process one bounded step; never approve, repeat a generation or refund an uncertain hold');echo '<button class="df-button">'.($j['state']==='WAITING'?'Check background result':'Start one research item').'</button></form>';}
   if(in_array($j['state'],['QUEUED','WAITING','UNKNOWN','BLOCKED','HELD','RESERVED'],true)){$this->form('cancel',$j);$this->confirm('Cancel locally; any existing provider work or monetary hold remains subject to reconciliation');echo '<button class="df-button">Cancel local run</button></form>';}
   if(in_array($j['state'],['QUEUED','WAITING','RESERVING','RESERVED','DISPATCHING','POLLING','INTAKING'],true)){$this->form('recover',$j);$this->confirm('Record an expired interrupted worker as unknown without retry or refund');echo '<button class="df-button">Recover interrupted evidence</button></form>';}
   foreach($j['results']as $r)echo '<p><a href="'.esc_url(add_query_arg(['df_view'=>'research','df_shop'=>$shop,'df_research_version'=>$r['result_sha256']],$this->baseUrl())).'#df-commercial-research">Open three concepts, source-backed brief and separate human review</a></p>';
   echo '</details>';
  }echo '</section>';
 }
 public function process(array $post):array|WP_Error {
  $shop=$post['shop_key']??null;if(!is_string($shop))return ResearchExecutionJournal::error('scope');$gate=ResearchExecutionJournal::access($shop);if($gate instanceof WP_Error)return $gate;if(($post['confirm']??null)!=='1')return ResearchExecutionJournal::error('confirmation');$op=$post['operation']??null;
  if($op==='research_queue_enqueue'){
   $sources=$post['sources']??null;if(!is_array($sources)||!is_string($post['request_key']??null)||!is_string($post['run_id']??null)||!is_string($post['started_at']??null))return ResearchExecutionJournal::error('input');
   $max=$this->number($post['maximum']??null);$days=$this->number($post['freshness_days']??null);if($max===null||$days===null)return ResearchExecutionJournal::error('input');$v=$this->execution->enqueue($shop,array_values($sources),['version'=>'shop2-research-run-v1','max_opportunities'=>$max,'freshness_days'=>$days,'per_task_ceiling'=>$post['per_task_ceiling']??null,'currency'=>$post['currency']??null],['run_id'=>$post['run_id'],'started_at'=>$post['started_at']],$post['request_key']);
  }else{
   $id=$this->number($post['research_job_id']??null);$event=$post['expected_event']??null;if($id===null||!is_string($event)||!preg_match('/^[a-f0-9]{64}$/D',$event))return ResearchExecutionJournal::error('input');$job=$this->execution->read($shop,$id);if($job instanceof WP_Error)return $job;if($job['event_sha256']!==$event)return ResearchExecutionJournal::error('stale_event');
   if($op==='research_queue_reconcile'){$usage=$this->number($post['usage_id']??null);$f=$_FILES['statement_file']??null;if($usage===null||!is_array($f)||($f['error']??null)!==UPLOAD_ERR_OK||!is_int($f['size']??null)||$f['size']<2||$f['size']>32768||!is_string($f['tmp_name']??null)||!is_uploaded_file($f['tmp_name']))return ResearchExecutionJournal::error('statement_upload');$raw=file_get_contents($f['tmp_name'],false,null,0,32769);if(!is_string($raw)||strlen($raw)>32768)return ResearchExecutionJournal::error('statement_upload');$reviewed=$this->execution->reconcile($shop,$id,$event,$usage,$raw,true);if($reviewed instanceof WP_Error)return $reviewed;$v=$job;
   }elseif($op==='research_queue_quote'){
    $f=$_FILES['quote_file']??null;if(!is_array($f)||($f['error']??null)!==UPLOAD_ERR_OK||!is_int($f['size']??null)||$f['size']<1||$f['size']>32768||!is_string($f['tmp_name']??null)||!is_uploaded_file($f['tmp_name']))return ResearchExecutionJournal::error('quote_upload');$raw=file_get_contents($f['tmp_name'],false,null,0,32769);$q=is_string($raw)?json_decode($raw,true):null;$contract=$job['identity']['contracts'][$job['index']]??null;if(!is_array($q)||!is_array($contract)||($q['request_sha256']??null)!==$contract['request_sha256']||($q['model']??null)!==$contract['model']||($q['currency']??null)!==$job['identity']['options']['currency'])return ResearchExecutionJournal::error('quote_identity');$saved=(new MonetaryReservationRepository())->reviewQuote($shop,$raw,'CONFIRM_PROVIDER_QUOTE');if($saved instanceof WP_Error)return $saved;$v=$job;
   }else $v=match($op){'research_queue_step'=>$this->execution->step($shop,$id,$event),'research_queue_cancel'=>$this->execution->cancel($shop,$id,$event),'research_queue_recover'=>$this->execution->recover($shop,$id,$event),default=>ResearchExecutionJournal::error('operation')};
  }
  return $v instanceof WP_Error?$v:['hash'=>$v['identity']['sources'][0],'research_job_id'=>$v['id'],'research_job'=>$v];
 }
 private function baseUrl():string {$id=get_queried_object_id();$url=$id>0?get_permalink($id):home_url('/');return is_string($url)?$url:home_url('/');}
 private function number(mixed $v):?int {return is_string($v)&&preg_match('/^[1-9][0-9]{0,8}$/D',$v)?(int)$v:null;}
 private function form(string $op,?array $job=null):void {echo '<form method="post" enctype="multipart/form-data" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="digiforge_commercial_research"><input type="hidden" name="operation" value="research_queue_'.esc_attr($op).'"><input type="hidden" name="shop_key" value="personalized_pod"><input type="hidden" name="return_url" value="'.esc_attr($this->baseUrl()).'">';if($job!==null)echo '<input type="hidden" name="research_job_id" value="'.esc_attr((string)$job['id']).'"><input type="hidden" name="expected_event" value="'.esc_attr($job['event_sha256']).'">';wp_nonce_field('digiforge_commercial_research');}
 private function confirm(string $text):void {echo '<p><label><input type="checkbox" name="confirm" value="1" required> '.esc_html($text).'</label></p>';}
}
